var CREATIVE_OS_DEMO={"ws":{"id":"ws_zencrevia","name":"ZenCrevia","logo":"ZC","logoImg":null,"favicon":null,"tagline":"Team operations workspace","timeZone":"Asia/Jakarta","workingDays":[1,2,3,4,5],"workStart":"09:00","workEnd":"18:00","theme":{"accent":"#1F4FD8","secondary":"#C6F24E","appearance":"light","density":"comfortable","radius":"round","font":"system"},"autoHide":{"tasks":"month","taskDays":30,"projects":"month","projectDays":30},"labels":[{"id":"lb_gd","name":"Graphic Designer","color":"#1F4FD8"},{"id":"lb_ve","name":"Video Editor","color":"#7C3AED"},{"id":"lb_mo","name":"Motion","color":"#D97706"},{"id":"lb_cw","name":"Copywriter","color":"#DB2777"},{"id":"lb_ui","name":"UI/UX","color":"#0F766E"},{"id":"lb_ph","name":"Photographer","color":"#16A34A"},{"id":"lb_cm","name":"Compliance","color":"#DC2626"}],"taskFields":[],"brand":{"primary":"#0B2A5B","palette":[{"name":"HSB Navy","hex":"#0B2A5B"},{"name":"Signal Blue","hex":"#1F4FD8"},{"name":"Paper","hex":"#F4F6FA"},{"name":"Bull Green","hex":"#16A34A"},{"name":"Bear Red","hex":"#DC2626"}],"headlineFont":"Poppins","bodyFont":"Inter","cjkFont":"Noto Sans","voice":"Calm, precise, never hyped. Short sentences. We talk about risk before reward. No profit claims, no exclamation marks, no rocket emojis.","photography":"Real people at a desk or on a phone, cool daylight. No stacks of cash, no Lamborghinis, no stock “success” imagery. Charts are illustration, never a real account screenshot.","guidelines":"as6","logoNotes":"Primary logo on white or paper. Mono white on navy only. Minimum clear space = height of the “H”. Regulator lockup always sits with the logo in the footer."},"briefFields":[["objective","Objective"],["background","Background"],["audience","Audience"],["deliverables","Deliverables"],["keyMessage","Key message"],["copy","Copy"],["cta","CTA"],["platform","Platform"],["dimensions","Dimensions"],["brand","Brand requirements"],["mandatory","Mandatory elements"],["references","References"],["notes","Additional notes"]],"notifPrefs":{"email":true,"assigned":true,"mention":true,"comment":true,"revision":true,"approval":true,"deadline":true,"missed":true,"upload":true,"request":true,"request_status":true,"status":false,"transition":false}},"roles":[["admin","Admin","Full workspace access"],["creative_lead","Creative Lead","Create projects/tasks, assign, review, approve, analytics"],["team_lead","Team Lead","Manage team workload, assign and review team tasks"],["member","Member","Work on assigned tasks, upload, comment, submit for review"],["viewer","Viewer","View everything, submit requests and comment"]],"workflow":[{"id":"backlog","kind":"queue","name":"Backlog","color":"gray"},{"id":"todo","kind":"queue","name":"To Do","color":"gray"},{"id":"progress","kind":"work","name":"In Progress","color":"blue"},{"id":"review","kind":"review","name":"Internal Review","color":"orange"},{"id":"compliance","kind":"review","name":"Compliance","color":"purple"},{"id":"revision","kind":"revision","name":"Revision","color":"red"},{"id":"approved","kind":"closed","name":"Approved","color":"green"},{"id":"delivered","kind":"closed","name":"Delivered","color":"green"},{"id":"done","kind":"closed","name":"Done","color":"green"},{"id":"declined","kind":"closed","name":"Declined","color":"red"}],"briefTemplates":[{"id":"social","name":"Social Media","description":"Feed, stories, reels","fields":["objective","audience","deliverables","keyMessage","copy","cta","platform","dimensions","brand","mandatory","references","notes"],"required":["objective","deliverables","platform"]},{"id":"banner","name":"Banner","description":"Web and app banners","fields":["objective","background","audience","deliverables","keyMessage","copy","cta","platform","dimensions","brand","mandatory","references","notes"],"required":["objective","deliverables","dimensions"]},{"id":"presentation","name":"Presentation","description":"Decks","fields":["objective","background","audience","deliverables","keyMessage","brand","references","notes"],"required":["objective"]},{"id":"branding","name":"Branding","description":"Identity work","fields":["objective","background","audience","deliverables","keyMessage","brand","mandatory","references","notes"],"required":["objective","deliverables"]},{"id":"video","name":"Video","description":"Video and motion","fields":["objective","background","audience","deliverables","keyMessage","copy","cta","platform","dimensions","mandatory","references","notes"],"required":["objective","deliverables","platform"]},{"id":"print","name":"Print","description":"Posters, menus, packaging","fields":["objective","audience","deliverables","copy","dimensions","brand","mandatory","references","notes"],"required":["objective","dimensions"]},{"id":"general","name":"General Creative Request","description":"Anything else","fields":["objective","background","audience","deliverables","keyMessage","platform","dimensions","brand","mandatory","references","notes"],"required":["objective"]}],"customFields":[{"id":"channel","name":"Channel","type":"select","options":["Web","App","Social","Email","Webinar","Paid Ads","OOH","Branch"]},{"id":"budget","name":"Budget (IDR m)","type":"number","options":[]},{"id":"legal","name":"Compliance check","type":"checkbox","options":[]}],"tags":["banner","web","print","branch","social","video","app","ui","brand","doc","email","education","webinar","ooh","copy","deck","compliance"],"cloud":[{"id":"gdrive","name":"Google Drive","connected":false,"account":"","folder":"/ZenCrevia","lastSync":12,"color":"#1FA463","config":{"autoUpload":true,"publicLinks":false}}],"knowledge":[{"id":"k1","folder":"Getting Started","title":"Creative request to approval — how work flows","by":"zein","ago":14400,"fav":true,"pinned":true,"body":"# How work flows\n\nEvery piece of work follows the same path so nobody has to ask where something is.\n\n1. **Request** — Marketing submits a creative request.\n2. **Brief** — a lead turns it into a structured creative brief.\n3. **Production** — the assignee uploads versions.\n4. **Review** — reviewer approves or requests revision with specific feedback.\n5. **Delivery** — approved files go to the delivery bucket.\n\n> Rule of thumb: if it is not in ZenCrevia, it is not a task."},{"id":"k2","folder":"Compliance SOP","title":"What compliance will reject","by":"zein","ago":17280,"fav":true,"pinned":true,"body":"# What compliance will reject\n\nSend it to the **Compliance** stage before it goes anywhere public. These come back every single time:\n\n1. Any number presented as an expected return.\n2. The words *pasti*, *dijamin*, *bebas risiko*, or an equivalent in English.\n3. A screenshot of a real account P/L, even blurred.\n4. A risk disclaimer under 11pt, or below 4.5:1 contrast.\n5. Missing regulator lockup in the footer.\n6. Testimonials that mention a profit amount.\n\nWhen in doubt: describe the tool, not the outcome."},{"id":"k2b","folder":"Design SOP","title":"Review etiquette","by":"laura","ago":43200,"fav":false,"pinned":false,"body":"# Review etiquette\n\n- Review within **one working day**.\n- Use image annotations for placement feedback; use comments for direction.\n- One revision round per version — batch your feedback.\n- Internal comments stay internal. Stakeholder-visible comments are written for the stakeholder.\n- Anything public-facing goes through **Compliance** after internal review, never instead of it."},{"id":"k3","folder":"Brand Guidelines","title":"Color","by":"laura","ago":86400,"fav":true,"pinned":false,"body":"# Color\n\nPrimary **HSB Navy** `#0B2A5B`. Support with signal blue `#1F4FD8` and paper `#F4F6FA`.\n\n- Green `#16A34A` and red `#DC2626` are **market colours only** — up and down. Never use them decoratively.\n- The risk disclaimer must clear 4.5:1 contrast on whatever it sits on. No exceptions."},{"id":"k4","folder":"Brand Guidelines","title":"Typography","by":"zein","ago":7200,"fav":false,"pinned":false,"body":"# Typography\n\nHeadlines: **Poppins** (600/700).\nBody: **Inter**.\nNumbers in charts and price tables: **Inter tabular figures**, always.\n\n| Role | Size | Leading |\n|---|---|---|\n| Display | 64–96 | 0.95 |\n| Headline | 32–48 | 1.05 |\n| Body | 15–17 | 1.5 |\n| Disclaimer | 11 min | 1.35 |"},{"id":"k5","folder":"Design SOP","title":"Photography","by":"sarah","ago":64800,"fav":false,"pinned":false,"body":"# Photography\n\nReal people at a desk or on a phone, cool daylight. No stacks of cash, no supercars, no stock “success” imagery — compliance rejects all three on sight. Charts are illustration; never screenshot a real account."},{"id":"k6","folder":"File Naming","title":"Naming convention","by":"zein","ago":129600,"fav":true,"pinned":false,"body":"# Naming convention\n\n`{project}-{deliverable}-v{n}.{ext}`\n\nExamples:\n\n- `hsbpro-hero-v2.psd`\n- `standee-branch12-v1.ai`\n\nFinal files get the suffix `-FINAL` and are copied to the S3 delivery bucket."},{"id":"k7","folder":"Export Guidelines","title":"Web and app exports","by":"rizky","ago":36000,"fav":false,"pinned":false,"body":"# Web and app exports\n\n- Hero: 1920×720 WebP, ≤ 350 KB\n- App splash: 1170×2532 PNG @2x\n- Always export a 2x and 1x variant; name them `@2x` and `@1x`."},{"id":"k8","folder":"Social Specs","title":"Instagram and TikTok","by":"andi","ago":21600,"fav":false,"pinned":true,"body":"# Instagram and TikTok\n\n| Format | Size | Safe zone |\n|---|---|---|\n| Feed | 1080×1350 | 80 px sides |\n| Story / Reels | 1080×1920 | 250 px top, 340 px bottom |\n| TikTok | 1080×1920 | 300 px bottom |"},{"id":"k9","folder":"Video SOP","title":"Reels and TikTok delivery","by":"andi","ago":10080,"fav":false,"pinned":false,"body":"# Reels and TikTok delivery\n\n- Master: ProRes 422, 1080×1920, 30 fps.\n- Deliver H.264 ≤ 30 MB with burned-in captions.\n- Sound-on hook in the first second; logo end card 1.5 s."},{"id":"k10","folder":"Getting Started","title":"Weekly creative sync","by":"zein","ago":10080,"fav":false,"pinned":false,"body":"# Weekly creative sync\n\nMonday 10:00. Agenda comes from the dashboard: overdue first, then needs review, then workload."}]},CREATIVE_OS_DEMO_SRC="/assets/demo-data.dce6395f22.js";
