function calItems(list,opts){ var byDay={}; list.forEach(function(t){ var k=iso(t.due); (byDay[k]=byDay[k]||[]).push({type:"task",o:t}); }); (S.filters.archived?PROJECTS:liveProjects()).filter(function(p){ return !(opts&&opts.compact)||list.some(function(t){ return inProject(t,p.id); }); }).forEach(function(p){ p.milestones.forEach(function(ms){ var k=iso(ms.due); (byDay[k]=byDay[k]||[]).push({type:"ms",o:ms,p:p}); }); if (p.status!=="done"){ var k2=iso(p.due); (byDay[k2]=byDay[k2]||[]).push({type:"pdue",o:p}); } }); return byDay; }
