function milestoneRows(p){ if (!p.milestones.length) return emptyBox("No milestones","Add the checkpoints that matter."); return p.milestones.slice().sort(function(a,b){ return a.due-b.due; }).map(function(m){ var i=p.milestones.indexOf(m); return '<div class="ms"><span class="chk'+(m.done?" on":"")+'" onclick="toggleMs(\''+p.id+'\','+i+')">'+(m.done?I.check:'')+'</span><div class="t'+(m.done?" done":"")+'" style="font-weight:600">'+esc(m.name)+'</div><span class="due '+(!m.done&&m.due<0?"over":(!m.done&&m.due===0?"today":""))+'">'+dueDate(m.due)+' · '+dueTxt(m.due)+'</span>'+(canI.editProject?'':'')+'<button class="iconbtn flat" style="width:26px;height:26px" title="Edit milestone" onclick="editMilestoneModal(\''+p.id+'\','+i+')">'+I.edit+'</button></div>'; }).join(""); }
