function assetsFiltered(){ var q=S.assetQuery.toLowerCase(); return ASSETS.filter(function(a){ if (S.assetFolder==="brand"&&!a.brand) return false; if (S.assetFolder!=="all"&&S.assetFolder!=="cloud"&&S.assetFolder!=="brand"&&a.folder!==S.assetFolder) return false; if (S.assetFolder==="cloud"&&a.source==="local") return false; if (q&&a.name.toLowerCase().indexOf(q)<0&&a.tags.join(" ").toLowerCase().indexOf(q)<0) return false; return true; }); }
function renderAssets(){ driveOnly(); var h='<div class="pagehead m-head"><div><h1>'+tr("Assets")+'</h1><div class="muted" style="margin-top:4px">'+ASSETS.length+' '+tr("assets")+' · '+ASSETS.filter(function(a){return a.brand;}).length+' '+tr("brand assets")+' · '+ASSETS.filter(function(a){return a.source!=="local";}).length+' '+tr("linked from Google Drive")+'</div></div><div class="actions"><div class="ptabs"><button class="tab'+(S.assetTab==="library"?" on":"")+'" onclick="S.assetTab=\'library\';renderScreen(false)">'+tr("Asset library")+'</button><button class="tab'+(S.assetTab==="brand"?" on":"")+'" onclick="S.assetTab=\'brand\';renderScreen(false)">'+tr("Brand library")+'</button></div>'+(canI.manageAssets()?'<button class="btn m-icon" aria-label="'+attr(tr("Link Google Drive"))+'" onclick="linkCloudModal(\'asset\')">'+driveIcon()+'<span class="m-label">'+tr("Link Google Drive")+'</span></button><button class="btn desktop-only" onclick="go(\'settings\',\'integrations\')">'+I.settings+tr("Google Drive settings")+'</button><button class="btn primary m-primary" aria-label="'+attr(tr("Upload asset"))+'" onclick="uploadAssetModal()">'+I.up+tr("Upload asset")+'</button>':'')+'</div></div>';
  h+=S.assetTab==="brand"?brandLibrary():assetLibrary(); document.getElementById("content").innerHTML=h; }
function assetLibrary(){ var list=assetsFiltered(); var cnt=function(f){ return ASSETS.filter(function(a){ return f==="all"?true:f==="cloud"?a.source!=="local":f==="brand"?a.brand:a.folder===f; }).length; };
  var h='<div class="assets"><div class="asset-side"><div class="folders"><button class="'+(S.assetFolder==="all"?"on":"")+'" onclick="S.assetFolder=\'all\';renderScreen(false)">'+I.assets+'All assets<span class="cnt">'+cnt("all")+'</span></button><button class="'+(S.assetFolder==="brand"?"on":"")+'" onclick="S.assetFolder=\'brand\';renderScreen(false)">'+I.star.replace("<svg",'<svg class="i"')+'Brand assets<span class="cnt">'+cnt("brand")+'</span></button><button class="'+(S.assetFolder==="cloud"?"on":"")+'" onclick="S.assetFolder=\'cloud\';renderScreen(false)">'+driveIcon()+'Cloud-linked<span class="cnt">'+cnt("cloud")+'</span></button><div class="fsep"></div>'+ASSET_FOLDERS.map(function(f){ return '<div class="folder-item"><button class="'+(S.assetFolder===f.id?"on":"")+'" onclick="S.assetFolder='+jsq(f.id)+';renderScreen(false)">'+I.projects+'<span class="fname">'+esc(f.name)+'</span><span class="cnt">'+cnt(f.id)+'</span></button>'+(canI.manageAssets()?'<button type="button" class="folder-edit" data-folder="'+attr(f.id)+'" title="'+attr(tr("Edit folder"))+'" aria-label="'+attr(tr("Edit folder"))+'" onclick="editFolderModal('+jsq(f.id)+')">'+I.edit+'</button>':'')+'</div>'; }).join("")+(canI.manageAssets()?'<button onclick="newFolderModal()" style="color:var(--color-primary)">'+I.plus.replace("<svg",'<svg class="i"')+'New folder</button>':'')+'</div>';
  h+='<div class="panel" style="margin-top:14px"><div class="panel-head"><span class="sq">'+I.cloud+'</span><h2>Storage</h2></div><div class="panel-body pad" style="display:flex;flex-direction:column;gap:8px">'+WS.cloud.map(function(c){ return '<button class="storage-account" onclick="go(\'settings\',\'integrations\')" title="Open Google Drive settings"><span class="drive-storage-logo">'+driveIcon()+'</span><span style="flex:1;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;text-align:left">'+esc(c.name)+'</span>'+(c.connected?'<span class="badge ok">on</span>':'<span class="badge">off</span>')+I.settings+'</button>'; }).join("")+'</div></div></div>';
  var fopts=[["all",tr("All assets")],["brand",tr("Brand assets")],["cloud",tr("Cloud-linked")]].concat(ASSET_FOLDERS.map(function(f){ return [f.id,f.name]; }));
  h+='<div><div class="toolbar asset-toolbar" style="margin-bottom:12px"><select class="asset-folder-select mobile-only" aria-label="'+attr(tr("Folder"))+'" onchange="S.assetFolder=this.value;renderScreen(false)">'+fopts.map(function(o){ return '<option value="'+attr(o[0])+'"'+(S.assetFolder===o[0]?" selected":"")+'>'+esc(o[1])+' ('+cnt(o[0])+')</option>'; }).join("")+'</select>'+(canI.manageAssets()&&byId(ASSET_FOLDERS,S.assetFolder)?'<button type="button" class="iconbtn mobile-only folder-edit-m" title="'+attr(tr("Edit folder"))+'" aria-label="'+attr(tr("Edit folder"))+'" onclick="editFolderModal('+jsq(S.assetFolder)+')">'+I.edit+'</button>':'')+'<input type="text" placeholder="'+tr("Filter by name or tag…")+'" value="'+attr(S.assetQuery)+'" oninput="S.assetQuery=this.value;renderAssetsBody()" style="flex:1;max-width:320px"><span class="hint" id="assetCount">'+list.length+' '+tr("shown")+'</span><span class="spacer"></span><div class="seg"><button class="'+(S.assetView==="grid"?"on":"")+'" onclick="S.assetView=\'grid\';renderScreen(false)">'+tr("Grid")+'</button><button class="'+(S.assetView==="list"?"on":"")+'" onclick="S.assetView=\'list\';renderScreen(false)">'+tr("List")+'</button></div></div><div id="assetsBody">'+assetsBody(list)+'</div></div></div>'; return h; }
function renderAssetsBody(){ var list=assetsFiltered(),el=document.getElementById("assetsBody"),count=document.getElementById("assetCount"); if(el)el.innerHTML=assetsBody(list); if(count)count.textContent=list.length+" "+tr("shown"); }
function assetsBody(list){ if (!list.length) return '<div class="panel">'+emptyBox("No assets here","Upload a file or link one from Google Drive.",driveIcon(),canI.manageAssets()?'<button class="btn primary sm" style="margin-top:6px" onclick="linkCloudModal(\'asset\')">'+driveIcon()+'Link Google Drive</button>':'')+'</div>';
  if (S.assetView==="list") return '<div class="panel"><div class="tbl-wrap"><table class="tbl"><thead><tr><th>Name</th><th>Type</th><th>Folder</th><th>Source</th><th>Size</th><th>Version</th><th>Updated</th></tr></thead><tbody>'+list.map(function(a){ return '<tr onclick="openAsset('+jsq(a.id)+')"><td class="t"><span class="cell-flex"><span class="ficon" style="background:'+attr(a.color)+';width:26px;height:26px;font-size:8px">'+assetChip(a)+'</span>'+esc(a.name)+(a.brand?' <span class="badge">brand</span>':'')+'</span></td><td>'+esc(a.type)+'</td><td>'+esc((byId(ASSET_FOLDERS,a.folder)||{name:"—"}).name)+'</td><td>'+srcBadge(srcOf(a))+'</td><td class="mono">'+esc(a.size)+'</td><td class="mono">v'+a.ver+'</td><td class="mono">'+ago(a.ago,a.createdAt)+'</td></tr>'; }).join("")+'</tbody></table></div></div>';
  return '<div class="agrid">'+list.map(function(a){ var s=SRC[srcOf(a)]; return '<div class="acard" onclick="openAsset('+jsq(a.id)+')"><div class="apv" style="background:'+a.color+(a.img?';background-image:url('+a.img+')':'')+'">'+(a.source!=="local"?'<span class="src" style="color:'+s.c+'">'+driveIcon()+s.l+'</span>':'')+(a.brand?'<span class="star">'+I.star.replace("<svg",'<svg width="14" height="14" fill="currentColor" stroke="currentColor"')+'</span>':'')+(a.img?'':assetFace(a,34))+'</div><div class="ab"><div class="at" title="'+attr(a.name)+'">'+esc(a.name)+'</div><div class="am"><span class="mono">v'+a.ver+'</span><span>·</span><span>'+esc(a.size)+'</span><span>·</span><span>'+ago(a.ago,a.createdAt)+'</span></div><div class="chips" style="margin-top:2px">'+a.tags.slice(0,3).map(function(t){ return '<span class="badge">'+esc(t)+'</span>'; }).join("")+'</div></div></div>'; }).join("")+'</div>'; }
function openAsset(id){ var a=asset(id); var cl=cloudOf(a.source); var used=TASKS.filter(function(t){ return t.files.some(function(f){ return f.name===a.name||(!!a.url&&f.url===a.url); }); }); var ed=canI.manageAssets(); var ro=ed?"":" disabled"; var canName=API.on?(ed||a.by===ME):ed;
  var body='<div id="as_tile" style="height:180px;border-radius:var(--radius);background:'+attr(a.color)+(a.img?';background-image:url('+a.img+');background-size:cover;background-position:center':'')+';display:grid;place-items:center;color:#fff;font-family:var(--font-mono);font-weight:700">'+(a.img?'':a.icon?assetFace(a,44):esc(typeExt(a).toUpperCase()))+'</div>'+'<div style="display:flex;gap:8px;align-items:center;flex-wrap:wrap">'+(a.img||/drive\.google/.test(a.url||"")?'<button class="btn sm ink" onclick="previewModal({title:'+jsq(a.name)+',img:asset('+jsq(id)+').img,driveId:(asset('+jsq(id)+').url.match(/\\/d\\/([^\\/]+)/)||[])[1],url:asset('+jsq(id)+').url})">'+I.eye+'Preview</button>':'')+'</div>'+(ed?'<div style="display:flex;gap:8px;align-items:center;flex-wrap:wrap"><button class="btn sm" onclick="pickThumb('+jsq(id)+')">'+I.up+(a.img?"Change thumbnail":"Add thumbnail")+'</button>'+(a.img?'<button class="btn sm ghost" onclick="assetSet('+jsq(id)+',\'img\',null);openAsset('+jsq(id)+')">Remove</button>':'')+'<span class="hint">JPG, PNG, or WebP. Recommended ratio: 3:2.</span></div>'+(a.img?'':assetIconPicker(a)):'')+
    '<div class="meta asset-meta" style="margin:0"><div><div class="k">Type</div><div class="v"><select'+ro+' onchange="assetSet('+jsq(id)+',\'type\',this.value)">'+ASSET_TYPES.map(function(t){ return '<option value="'+attr(t)+'"'+(a.type===t?" selected":"")+'>'+esc(t)+'</option>'; }).join("")+'</select></div></div><div><div class="k">Folder</div><div class="v"><select'+ro+' aria-label="'+attr(tr("Folder"))+'" onchange="assetSet('+jsq(id)+',\'folder\',this.value||null)"><option value=""'+(byId(ASSET_FOLDERS,a.folder)?"":" selected")+'>'+esc(tr("No folder"))+'</option>'+ASSET_FOLDERS.map(function(f){ return '<option value="'+attr(f.id)+'"'+(a.folder===f.id?" selected":"")+'>'+esc(f.name)+'</option>'; }).join("")+'</select></div></div><div><div class="k">Brand asset</div><div class="v"><input'+ro+' type="checkbox" style="width:16px;height:16px" '+(a.brand?"checked":"")+' onchange="assetSet('+jsq(id)+',\'brand\',this.checked)"><span class="hint">show in Brand library</span></div></div><div><div class="k">Source</div><div class="v">'+srcBadge(srcOf(a))+'</div></div><div><div class="k">Version</div><div class="v mono">v'+a.ver+' · '+esc(a.size)+'</div></div><div><div class="k">Uploaded by</div><div class="v">'+av(a.by)+esc(first(a.by))+'</div></div><div><div class="k">Updated</div><div class="v mono">'+ago(a.ago,a.createdAt)+'</div></div></div>'+
    (a.url?'<div class="field"><label>Cloud location</label><div style="display:flex;gap:8px"><input value="'+attr(a.url)+'" readonly style="font-family:var(--font-mono);font-size:12px"><button class="btn" onclick="openExternal('+jsq(a.url)+')">'+I.ext+'Open</button></div>'+(cl&&cl.connected?'<div class="hint" style="margin-top:6px">Linked via '+esc(cl.name)+' · '+esc(cl.account)+'</div>':'')+'</div>':'')+
    fieldHtml("as_desc","Description",'<input'+ro+' id="as_desc" value="'+attr(a.description||"")+'" onchange="assetSet('+jsq(id)+',\'description\',this.value)">')+fieldHtml("as_tags","Tags",tagPicker("as_tags_"+id,a.tags||[],function(value){ assetSet(id,"tags",value); },{readonly:!!ro}))+
    '<div><div class="eyebrow" style="margin-bottom:6px">'+tr("Used in")+' '+uiCount(used.length,"task","tasks")+'</div>'+(used.length?'<div class="agenda">'+used.map(function(t){ return taskRow(t); }).join("")+'</div>':'<div class="hint">Attach it from a task’s Files tab.</div>')+'</div>';
  openModal(canName?'<input class="asset-name-input" id="as_name" data-nofocus maxlength="240" value="'+attr(a.name)+'" title="'+attr(tr("Click to rename"))+'" aria-label="'+attr(tr("Asset name"))+'" onkeydown="if(event.key===\'Enter\'){event.preventDefault();this.blur();}" onblur="assetRename('+jsq(id)+',this)">':esc(a.name),body,(ed?'<button class="btn danger-soft" onclick="deleteAsset('+jsq(id)+')">'+I.trash+'Delete</button>':'')+'<span class="spacer"></span>'+(ed?'<button class="btn" onclick="newVersionAsset('+jsq(id)+')">'+I.up+'New version</button>':'')+'<button class="btn primary" onclick="closeModal();renderScreen(false)">Done</button>',true); }
function pickThumb(id){ var inp=document.getElementById("fileInput"); inp.accept="image/*"; inp.onchange=function(){ var f=inp.files[0]; inp.value=""; if (!f) return; shrinkImage(f,1200,800,function(dataUrl){ assetSet(id,"img",dataUrl); toast("Thumbnail updated"); openAsset(id); }); }; inp.click(); }
function shrinkImage(file,maxW,maxH,cb,onError){ var fail=function(){var e=new Error("Could not read this image. Choose a PNG, JPG, or WebP file.");if(onError)onError(e);else toast(e.message,"bad");};var rd=new FileReader();rd.onerror=fail;rd.onload=function(){var img=new Image();img.onerror=fail;img.onload=function(){try{var r=Math.min(1,maxW/img.width,maxH/img.height),cv=document.createElement("canvas");cv.width=Math.max(1,Math.round(img.width*r));cv.height=Math.max(1,Math.round(img.height*r));cv.getContext("2d").drawImage(img,0,0,cv.width,cv.height);var out=cv.toDataURL("image/png");if(out.length>390000){out=cv.toDataURL("image/webp",0.8);while(out.length>390000&&cv.width>100){var next=document.createElement("canvas");next.width=Math.round(cv.width*0.8);next.height=Math.round(cv.height*0.8);next.getContext("2d").drawImage(cv,0,0,next.width,next.height);cv=next;out=cv.toDataURL("image/webp",0.75);}}if(out.length>390000)return fail();cb(out);}catch(e){fail();}};img.src=rd.result;};rd.readAsDataURL(file); }
function assetSet(id,k,v){ var a=asset(id); a[k]=v; persistAsset(a,false); }
function assetRename(id,input){ var a=asset(id); if(!a||!input) return; var v=String(input.value||"").trim().slice(0,240); if(!v){ input.value=a.name; return toast(tr("The name cannot be empty"),"bad"); } if(v===a.name){ input.value=v; return; } a.name=v; input.value=v; persistAsset(a,false); toast(tr("Name saved")); }
void 0;
function deleteAsset(id){ closeModal(); confirmModal("Delete asset?","Linked cloud files are unlinked, not deleted from the provider.",function(){ deleteAssetById(id); toast("Asset removed","bad"); },true); }
function newVersionAsset(id){ var inp=document.getElementById("fileInput"); inp.accept="*/*"; inp.onchange=function(){var f=inp.files[0];inp.value="";if(!f)return;uploadAny(f).then(function(u){var a=asset(id);if(!a)return; a.ver++;a.ago=0;a.source=u.source;a.url=u.url;a.img=u.preview||null;a.size=u.size;return persistAsset(a,false).then(function(saved){ if(saved===false)return false;toast("Version uploaded");openAsset(id);});}).catch(function(e){toast(e.message,"bad");});};inp.click(); }
