function assetIconSvg(k,px){ var d=ASSET_ICONS.filter(function(x){ return x[0]===k; })[0]; return d?'<svg class="asset-glyph" viewBox="0 0 24 24" style="width:'+px+'px;height:'+px+'px" fill="none" stroke="currentColor" stroke-width="'+(px>=32?1.6:2)+'" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'+d[2]+'</svg>':""; }
function assetFace(a,px){ var g=a&&a.icon?assetIconSvg(a.icon,px):"", ext='<span class="ext">'+esc(typeExt(a).toUpperCase())+'</span>'; return g?'<span class="asset-face">'+g+ext+'</span>':ext; }
function assetChip(a){ return (a&&a.icon&&assetIconSvg(a.icon,15))||esc(typeExt(a)); }
function assetIconPicker(a){ return '<div class="asset-icon-pick"><span class="hint">'+esc(tr("Or use an icon"))+'</span><div class="asset-icon-grid" role="group" aria-label="'+attr(tr("Thumbnail icon"))+'">'+ASSET_ICONS.map(function(x){ var on=a.icon===x[0]; return '<button type="button" class="asset-icon-opt'+(on?" on":"")+'" data-icon="'+attr(x[0])+'" aria-pressed="'+on+'" title="'+attr(tr(x[1]))+'" aria-label="'+attr(tr(x[1]))+'" onclick="assetIconPick('+jsq(a.id)+','+jsq(x[0])+')">'+assetIconSvg(x[0],18)+'</button>'; }).join("")+'</div></div>'; }
function assetIconPick(id,k){ var a=asset(id); if(!a||!canI.manageAssets()) return; var next=a.icon===k?"":k; assetSet(id,"icon",next);
  var tile=document.getElementById("as_tile"); if(tile&&!a.img) tile.innerHTML=next?assetFace(a,44):esc(typeExt(a).toUpperCase());
  document.querySelectorAll(".asset-icon-opt").forEach(function(b){ var on=b.getAttribute("data-icon")===next; b.classList.toggle("on",on); b.setAttribute("aria-pressed",String(on)); }); }
function editFolderModal(id){ var f=byId(ASSET_FOLDERS,id); if(!f||!canI.manageAssets()) return;
  openModal("Edit folder",fieldHtml("ef_name","Folder name",'<input id="ef_name" maxlength="80" value="'+attr(f.name)+'" onkeydown="if(event.key===\'Enter\'){event.preventDefault();saveFolderEdit('+jsq(id)+');}">')+fieldHtml("ef_type","Type",selectHtml("ef_type",ASSET_TYPES,f.type||"other")),
    '<button class="btn danger-soft" onclick="deleteFolderAsk('+jsq(id)+')">'+I.trash+'Delete</button><span class="spacer"></span><button class="btn" onclick="closeModal()">Cancel</button><button class="btn primary" onclick="saveFolderEdit('+jsq(id)+')">Save</button>'); }
function saveFolderEdit(id){ var f=byId(ASSET_FOLDERS,id); if(!f||!require(["ef_name"])) return; var name=val("ef_name").trim().slice(0,80); if(!name) return; f.name=name; f.type=val("ef_type"); closeModal(); renderScreen(false); persistFolderEdit(f).then(function(ok){ if(ok!==false) toast(tr("Folder saved")); }); }
function deleteFolderAsk(id){ var f=byId(ASSET_FOLDERS,id); if(!f) return; var n=ASSETS.filter(function(a){ return a.folder===id; }).length; closeModal();
  confirmModal("Delete folder?",esc(n?uiCount(n,"asset","assets")+" "+tr("stay in the library, without a folder."):tr("The folder is empty.")),function(){ deleteFolderById(id); toast(tr("Folder deleted"),"bad"); },true); }
function newFolderModal(){ openModal("New folder",fieldHtml("nf_name","Folder name",'<input id="nf_name" placeholder="e.g. Motion">')+fieldHtml("nf_type","Type",selectHtml("nf_type",ASSET_TYPES,"other")),'<button class="btn" onclick="closeModal()">Cancel</button><button class="btn primary" onclick="if(require([\'nf_name\'])){var f={id:uid(\'f\'),name:val(\'nf_name\'),type:val(\'nf_type\'),sort:ASSET_FOLDERS.length+1};ASSET_FOLDERS.push(f);closeModal();renderScreen(false);persistFolder(f)}">Create</button>'); }
function uploadAssetModal(){ window._assetImg=null; window._assetFile=null; window._assetUp=null; window._assetPending=false; window._assetSession=(window._assetSession||0)+1; openModal("Upload asset",'<div class="field"><label>File</label><div style="display:flex;gap:8px;align-items:center"><button class="btn" onclick="pickAssetFile()">'+I.up+'Choose file</button><span class="hint" id="ua_file">No file chosen</span></div></div><div id="ua_preview"></div><div class="hint">'+(storageKeepsFiles()?tr("Files are kept in full in")+" "+storageLabel()+".":tr("Images are saved as previews. Other files need a file storage — ask an admin to set one up in Settings."))+'</div>'+fieldHtml("ua_name","Name",'<input id="ua_name" placeholder="Display name">')+'<div class="field-row">'+fieldHtml("ua_type","Type",selectHtml("ua_type",ASSET_TYPES,"image"))+fieldHtml("ua_folder","Folder",selectHtml("ua_folder",[["",tr("No folder")]].concat(ASSET_FOLDERS.map(function(f){ return [f.id,f.name]; })),byId(ASSET_FOLDERS,S.assetFolder)?S.assetFolder:""))+'</div>'+fieldHtml("ua_tags","Tags",tagPicker("ua_tags",[],""))+'<label style="display:flex;gap:8px;align-items:center;font-size:var(--fs-sm)"><input type="checkbox" id="ua_brand"> Brand asset (show in Brand library)</label>','<button class="btn" onclick="closeModal()">Cancel</button><button class="btn primary" onclick="saveAsset()">Upload</button>'); }
function pickAssetFile(){ var inp=document.getElementById("fileInput"); inp.accept="*/*"; inp.onchange=function(){ var f=inp.files[0]; inp.value=""; if(!f)return; assetFileChosen(f); }; inp.click(); }
function assetFileChosen(f){ if(!f||!document.getElementById("ua_file")||!document.getElementById("modalWrap").classList.contains("open")) return; var session=window._assetSession, token=window._assetPick=(window._assetPick||0)+1; window._assetFile=f; window._assetUp=null; window._assetImg=null; window._assetPending=true; document.getElementById("ua_preview").innerHTML=""; document.getElementById("ua_file").textContent=f.name+" · "+tr("Uploading…"); var n=document.getElementById("ua_name"); if(!n.value)n.value=f.name;
  uploadAny(f,{forceDrive:true}).then(function(u){ if(session!==window._assetSession||token!==window._assetPick)return; window._assetUp=u; window._assetImg=u.preview||null; var pv=document.getElementById("ua_preview"); if(pv)pv.innerHTML=u.preview?'<img src="'+attr(u.preview)+'" style="max-width:100%;max-height:180px;border-radius:8px">':""; var el=document.getElementById("ua_file"); if(el)el.textContent=f.name+" · "+u.size+(u.driveId?" · Google Drive":""); }).catch(function(e){ if(session!==window._assetSession||token!==window._assetPick)return; window._assetUp=null; var el=document.getElementById("ua_file"); if(el)el.textContent=tr("Upload failed"); toast(e.message,"bad"); }).finally(function(){if(session===window._assetSession&&token===window._assetPick)window._assetPending=false;}); }
function saveAsset(){ if (!require(["ua_name"])) return; if(window._assetPending) return toast(tr("Wait for the upload to finish"),"bad"); if(!window._assetFile||!window._assetUp) return toast(tr("Choose a file first"),"bad"); var f=window._assetFile; var cols=["#7C3AED","#0F766E","#B45309","#1D4ED8","#BE185D","#2D6A4F"]; var a={id:uid("as"),name:val("ua_name"),type:val("ua_type"),folder:val("ua_folder"),tags:tagPickerValues("ua_tags"),size:f?(f.size/1048576).toFixed(1)+" MB":"—",ver:1,source:(window._assetUp&&window._assetUp.source)||"local",url:window._assetUp?window._assetUp.url:"",driveId:window._assetUp?window._assetUp.driveId||null:null,ago:0,color:cols[ASSETS.length%cols.length],by:ME,brand:document.getElementById("ua_brand").checked,description:""}; if (window._assetImg) a.img=window._assetImg; ASSETS.unshift(a); closeModal(); renderScreen(false); persistAsset(a,true).then(function(saved){if(saved!==false)toast(tr("Asset uploaded"));}); }
function linkCloudModal(target){ var c=driveOnly(); openModal(driveIcon()+" Link from Google Drive",'<p class="hint">Paste a Google Drive, Docs, Sheets, or Slides share link. The file stays in Drive; ZenCrevia stores the link and shows a preview whenever Drive allows embedding.</p>'+fieldHtml("lc_url","Google Drive share link",'<input id="lc_url" placeholder="https://drive.google.com/file/d/…" oninput="if(typeof linkNameSoon===\'function\')linkNameSoon(\'lc_url\',\'lc_name\',\'lc_hint\')">')+fieldHtml("lc_name",tr("Display name (optional)"),'<input id="lc_name" placeholder="'+attr(tr("Filled in from Drive when it can be read"))+'">')+'<p class="hint" id="lc_hint" style="min-height:1.3em;margin:-6px 0 8px"></p>'+(target==="asset"?'<div class="field-row">'+fieldHtml("lc_type","Type",selectHtml("lc_type",ASSET_TYPES,"document"))+fieldHtml("lc_folder","Folder",selectHtml("lc_folder",[["",tr("No folder")]].concat(ASSET_FOLDERS.map(function(f){ return [f.id,f.name]; })),byId(ASSET_FOLDERS,S.assetFolder)?S.assetFolder:""))+'</div>'+fieldHtml("lc_tags","Tags",tagPicker("lc_tags",[],"")):'')+'<div class="hint">'+(c.connected?'Drive is connected as '+esc(c.account||"your Google account"):'Connect Drive once in Settings before uploading files automatically.')+' <a href="#" onclick="closeModal();go(\'settings\',\'integrations\');return false" style="color:var(--color-primary);font-weight:600">Open Google Drive settings</a></div>','<button class="btn" onclick="closeModal()">Cancel</button><button class="btn primary" onclick="saveCloudLink(\''+target+'\')">Link and preview</button>'); }
function saveCloudLink(target){ if (!require(["lc_url"])) return; var url=val("lc_url"); if (!isDriveUrl(url)) return toast(tr("Use a Google Drive, Docs, Sheets, or Slides share link"),"bad"); var c=driveOnly();
  var typed=val("lc_name").trim(), type=target==="asset"?val("lc_type"):"", folder=target==="asset"?val("lc_folder"):"", tags=target==="asset"?tagPickerValues("lc_tags"):[];
  var btn=document.querySelector("#modal .btn.primary"); if(btn) btn.disabled=true;
  (typeof linkNameFor==="function"?linkNameFor(url,typed):Promise.resolve(typed||"Google Drive")).then(function(name){
    closeModal();
    if (target==="asset"){ var a={id:uid("as"),name:name,type:type,folder:folder,tags:tags,size:"—",ver:1,source:"gdrive",url:url,ago:0,color:SRC.gdrive.c,by:ME,brand:false,description:""}; ASSETS.unshift(a); toast(tr("Linked from Google Drive")); renderScreen(false); persistAsset(a,true); }
    else { var tk=task(S.drawerTask); editTaskWith(tk,function(t){ t.files.push(F(name,"document","gdrive","—",0,url)); log(t,"link",{name:name}); }).then(function(saved){ if(saved===false)return false; toast(tr("Google Drive file linked")); }); }
  }); }
function saveGDrive(signIn){ var c=cloudOf("gdrive"), draft={clientId:val("gd_client"),folderId:val("gd_folder"),account:val("cc_acc"),autoUpload:document.getElementById("gd_auto").classList.contains("on"),publicLinks:document.getElementById("gd_public").classList.contains("on")}; if(draft.publicLinks&&!((c.config||{}).publicLinks===true)) return confirmModal("Make every new upload public?","Anyone who receives a file link could open it without signing in. Use this only for approved non-sensitive files.",function(){saveGDriveApply(signIn,draft);},true); saveGDriveApply(signIn,draft); }
function saveGDriveApply(signIn,draft){ var c=cloudOf("gdrive"), old=c.config||{}, changed=old.clientId!==draft.clientId||old.folderId!==draft.folderId; if(changed){GD.token=null;GD.exp=0;gdClearAuth();c.connected=false;} c.config={clientId:draft.clientId,folderId:draft.folderId,autoUpload:draft.autoUpload,publicLinks:draft.publicLinks===true,verified:changed?null:(old.verified||null)}; c.account=draft.account||c.account; c.folder=c.config.folderId?tr("Drive folder ")+c.config.folderId:tr("My Drive"); if (!c.config.clientId) c.connected=false; persistWS(); closeModal(); if (S.screen==="assets"||S.screen==="settings") renderScreen(false); if (signIn&&c.config.clientId){ GD.token=null; gdToken({interactive:true}).then(function(saved){ if(saved===false)return false; toast(tr("Google Drive connected")); renderScreen(false); }).catch(function(e){ toast(tr("Google sign-in failed")+": "+e.message,"bad"); }); } else toast(tr("Google Drive settings saved")); }
function editCloud(id){ if (id==="gdrive") return editGDrive(); var c=cloudOf(id); openModal((c.connected?"Edit ":"Connect ")+esc(c.name),fieldHtml("cc_acc","Account / bucket",'<input id="cc_acc" value="'+attr(c.account)+'" placeholder="'+(id==="s3"?"bucket-name (region)":"name@company.com")+'">')+fieldHtml("cc_folder","Root folder / prefix",'<input id="cc_folder" value="'+attr(c.folder)+'" placeholder="'+(id==="s3"?"s3://bucket/path":"/ZenCrevia")+'">')+(id==="s3"?fieldHtml("cc_key","Access key",'<input id="cc_key" type="password" placeholder="Stored server-side, never in the browser">'):'<div class="hint">In production this opens the provider OAuth consent screen; the token is stored server-side.</div>'),'<button class="btn" onclick="cloudSettingsModal()">Back</button><button class="btn primary" onclick="if(require([\'cc_acc\'])){var c=cloudOf('+jsq(id)+');c.connected=true;c.account=val(\'cc_acc\');c.folder=val(\'cc_folder\');c.lastSync=0;persistWS();toast(c.name+\' connected\');cloudSettingsModal();if(S.screen===\'assets\'||S.screen===\'settings\')renderScreen(false)}">'+(c.connected?"Save":"Connect")+'</button>'); }
function syncCloud(){ editGDrive(); }
function disconnectCloud(id){ GD.token=null; GD.exp=0; gdClearAuth(); var c=cloudOf(id); if(c.config)c.config.verified=null; c.connected=false; persistWS(); toast(c.name+" "+tr("disconnected"),"bad"); cloudSettingsModal(); if (S.screen==="assets"||S.screen==="settings") renderScreen(false); }

var DRIVE_LOGO_DATA="/assets/google-drive-logo.2d6d3f4a92.webp";
