  h+='<section class="panel"><div class="panel-head"><span class="sq">'+I.knowledge+'</span><h2>Guidelines &amp; icons</h2></div>'+cards(byType("guideline").concat(byType("icon")))+'</section>';
  h+='<section class="panel" style="grid-column:1/-1"><div class="panel-head"><span class="sq">'+I.projects+'</span><h2>Templates</h2><span class="hint">Available while writing briefs and tasks</span></div>'+cards(byType("template"))+'</section>';
