function copyText(t){ if(!navigator.clipboard)return toast("Copy this value: "+t); return navigator.clipboard.writeText(t).then(function(saved){ if(saved===false)return false;toast("Copied");}).catch(function(){toast("Copy this value: "+t,"bad");}); }
function brandEdit(k,label){ openModal(label,fieldHtml("be_v",label,'<textarea id="be_v" style="min-height:120px">'+esc(WS.brand[k]||"")+'</textarea>'),'<button class="btn" onclick="closeModal()">Cancel</button><button class="btn primary" onclick="WS.brand[\''+k+'\']=val(\'be_v\');closeModal();renderScreen(false);persistWS();toast(\'Brand library updated\')">Save</button>'); }
function brandColorModal(i){ var c=i!=null?WS.brand.palette[i]:{name:"",hex:"#B45309"}; openModal(i!=null?"Edit color":"Add color",'<div class="field-row">'+fieldHtml("bc_name","Name",'<input id="bc_name" value="'+attr(c.name)+'">')+fieldHtml("bc_hex","Hex",'<div style="display:flex;gap:8px"><input type="color" id="bc_pick" value="'+c.hex+'" oninput="document.getElementById(\'bc_hex\').value=this.value"><input id="bc_hex" value="'+attr(c.hex)+'" style="font-family:var(--font-mono)"></div>')+'</div>',(i!=null?'<button class="btn danger-soft" onclick="WS.brand.palette.splice('+i+',1);closeModal();renderScreen(false);persistWS()">Remove</button>':'')+'<span class="spacer"></span><button class="btn" onclick="closeModal()">Cancel</button><button class="btn primary" onclick="if(require([\'bc_name\',\'bc_hex\'])){var p=WS.brand.palette=WS.brand.palette||[];var o={name:val(\'bc_name\'),hex:val(\'bc_hex\')};'+(i!=null?'p['+i+']=o;':'p.push(o);')+'closeModal();renderScreen(false);persistWS()}">Save</button>'); }
function uploadFontAsset(){uploadAssetModal();document.getElementById("ua_type").value="font";document.getElementById("ua_folder").value=byId(ASSET_FOLDERS,"font")?"font":(ASSET_FOLDERS[0]||{}).id;document.getElementById("ua_brand").checked=true;}
function brandTypeModal(){ var b=WS.brand; openModal("Typography",fieldHtml("bt_h","Headline font",'<input id="bt_h" value="'+attr(b.headlineFont||"")+'">')+fieldHtml("bt_b","Body font",'<input id="bt_b" value="'+attr(b.bodyFont||"")+'">')+fieldHtml("bt_c","CJK font (optional)",'<input id="bt_c" value="'+attr(b.cjkFont||"")+'">'),'<button class="btn" onclick="closeModal()">Cancel</button><button class="btn primary" onclick="WS.brand.headlineFont=val(\'bt_h\');WS.brand.bodyFont=val(\'bt_b\');WS.brand.cjkFont=val(\'bt_c\');closeModal();renderScreen(false);persistWS()">Save</button>'); }

