        aiShadowOn(g,aiLayerStyle("logo")); g.drawImage(mark,dx,dy,dw,dh); aiShadowOff(g); AI_TEXT_SPECS.logo={type:"image",src:logoSrc};aiAddHit("logo",dx,dy,dw,dh); finish();
