  im.onload = function(){
    AI_EXPAND = { srcUrl: src.url, layerId: src.layerId, baseW: im.naturalWidth, baseH: im.naturalHeight, top:0, right:0, bottom:0, left:0, ratio:"free", busy:false };
    aiExpandModal();
  };
