  var g = cv.getContext("2d");
  var im = new Image(); im.crossOrigin = "anonymous";
  im.onload = function(){
    g.clearRect(0,0,cv.width,cv.height);
    g.drawImage(im, t.cropX, t.cropY, t.cropW, t.cropH, padded ? t.dx : 0, padded ? t.dy : 0, t.cropW, t.cropH);
    cb(cv,t);
  };
