function emojiPicker(anchor,onPick){ EMOJI_PICK.cb=onPick; EMOJI_PICK.q=""; EMOJI_PICK.cat=emojiRecent().length?"recent":"smileys"; openMenu("ctxMenu",anchor,emojiPickerHtml(),"left"); var m=document.getElementById("ctxMenu"); m.classList.add("emoji-menu"); setTimeout(function(){ var i=m.querySelector(".emoji-search"); if(i) i.focus(); place(m,anchor); },10); }
