  var items=q?(custom?customEmojiFind(q):[]).concat(emojiIndex().filter(function(x){ return x.k.indexOf(q)>=0||x.e===q; })).slice(0,96):cat==="custom"&&custom?customEmojiItems():cat==="recent"?emojiRecent().filter(function(e){ return !/^:[a-z]/.test(e)||(custom&&customEmoji(e)); }).map(function(e){ return {e:e}; }):((EMOJI_CATEGORIES.filter(function(c){ return c[0]===cat; })[0]||EMOJI_CATEGORIES[0])[2].map(function(e){ return {e:e[0]}; }));
