function msgOpenMention(ta,q){ var c=conv(S.messageConversationId); CHAT_RUNTIME.mentionOpen=true; entityPicker({_deferred:true,kind:"person",anchor:msgCaretAnchor(ta),align:"left",initial:q,placeholder:tr("Mention someone…"),context:{members:convMembers(c),everyone:has("mention_everyone")||has("manage_teams")||c.type==="GROUP"||c.type==="DM"},onSelect:function(id){ msgInsertMention(id); },onClose:function(){ CHAT_RUNTIME.mentionOpen=false; var t=document.getElementById("msgInput"); if(t) t.focus(); }}); var ep=document.getElementById("entityPicker"); if(ep){ ep.classList.add("ep-mention"); var s=ep.querySelector(".ep-search"); if(s) s.setAttribute("tabindex","-1"); setTimeout(function(){ ta.focus(); },20); } }
