function msgStageUrl(url,fromBody,quiet){ var p=detectProvider(url); if(!p) return; var c=conv(S.messageConversationId), d=msgDraft(c.id); if(d.refs.some(function(r){return (r.normalizedUrl||r.url)===p.url;}))return; if(d.refs.length>=MSG_MAX_REFS){if(!quiet)toast(tr("Up to")+" "+MSG_MAX_REFS+" "+tr("attachments per message"),"bad");return;} if(p.provider==="ZENCREVIA"&&(p.resourceType==="task"||p.resourceType==="project")){var ent=p.resourceType==="task"?task(p.resourceId):project(p.resourceId);if(ent){d.refs.push({type:p.resourceType.toUpperCase(),entityId:p.resourceId,fallbackTitle:ent.title||ent.name,normalizedUrl:p.url,url:p.url,fromBody:!!fromBody,source:fromBody?"BODY":"ATTACH"});if(!quiet){CHAT_RUNTIME.focusComposer=true;renderMsgMain(true);}return;}} var ref={type:/^GOOGLE_/.test(p.provider)?"DRIVE_LINK":"URL",url:p.url,normalizedUrl:p.url,provider:p.provider,resourceType:p.resourceType,resourceId:p.resourceId,subtitle:smartSubtitle(p),title:"",state:"pending",fromBody:!!fromBody,source:fromBody?"BODY":"ATTACH"}; d.refs.push(ref); if(!quiet){CHAT_RUNTIME.focusComposer=true;renderMsgMain(true);} resolveSmartLink(url).then(function(r){ if(!r)return; Object.assign(ref,r); msgUploadRedraw(ref); }); }
