function msgDeliver(c,m){ m._pending=true; delete m.failed;
  apiFetch("POST","/api/messages/conversations/"+c.id+"/messages",{id:m.id,body:m.body,mentions:m.mentions,refs:m.refs,replyTo:m.replyTo}).then(function(saved){ delete m._pending; Object.assign(m,saved); if(S.screen==="messages"&&S.messageConversationId===c.id)renderMsgTimeline(true); }).catch(function(e){ delete m._pending; m.failed=true; fail(e,e.message); if(S.screen==="messages"&&S.messageConversationId===c.id)renderMsgTimeline(true); }); }
