function saveGroup(id){ var name=val("grpName"), sel=window._grpSel||[]; if(!name) return toast(tr("Give the group a name"),"bad"); if(sel.length<2) return toast(tr("Add at least one other member"),"bad"); if(!id&&!(has("create_group_chat")||has("view_all"))) return toast(tr("Your role cannot create groups"),"bad"); var c=id?conv(id):{id:uid("cv"),type:"GROUP",createdBy:ME,createdAt:new Date().toISOString(),pins:[],starredBy:[],readState:{},notificationLevel:{},_local:!API.on}; c.name=name; c.members=sel; if(!id) CONVERSATIONS.push(c); msgSave(); if(API.on) apiFetch(id?"PATCH":"POST",id?"/api/messages/conversations/"+id:"/api/messages/conversations",{id:c.id,type:"GROUP",name:name,members:sel}).catch(function(e){ toast(e.message,"bad"); }); closeModal(); openConversation(c.id); toast(tr(id?"Group saved":"Group created")); }
