  if(!raw||!raw.length) return null;
  var items=raw.map(function(it){
      return {title:String((it&&it.title)||"").trim().slice(0,90),
              detail:String((it&&it.detail)||"").trim().slice(0,320)}; })
    .filter(function(it){ return it.title&&it.detail; })
