function exportJSON(){ var ws=clone(WS); delete ws.people; var data={version:3,baseDate:iso(0),exportedAt:new Date().toISOString(),ws:ws,teams:TEAMS,people:PEOPLE,roles:ROLES,projects:PROJECTS,tasks:TASKS,requests:REQUESTS,folders:ASSET_FOLDERS,assets:ASSETS,knowledge:KNOWLEDGE,knowledgeFolders:(typeof KNOWLEDGE_FOLDERS!=="undefined"?KNOWLEDGE_FOLDERS:[]),views:VIEWS,notifs:NOTIFS,activity:ACTIVITY}; download(fileStamp().replace("workspace-report","backup")+".json",new Blob([JSON.stringify(data,null,2)],{type:"application/json"})); toast("Backup downloaded"); }
