function agCardHTML(x){return '<article class="panel ag-card"><button class="ag-cover" aria-label="'+attr(tr('View design')+': '+x.name)+'" onclick="agDetails(\''+x.id+'\')"><img loading="lazy" src="'+attr(x.thumb)+'" alt="'+attr(x.name)+'"></button><div class="ag-card-body"><div class="ag-card-title"><h2 data-no-translate title="'+attr(x.name)+'">'+esc(x.name)+'</h2><button class="iconbtn ag-favorite" title="'+attr(tr(x.favorite?'Remove favorite':'Add favorite'))+'" aria-pressed="'+x.favorite+'" aria-label="'+attr(tr(x.favorite?'Remove favorite':'Add favorite'))+'" onclick="agFavorite(\''+x.id+'\')"><svg class="i" viewBox="0 0 24 24" aria-hidden="true"'+(x.favorite?' style="fill:currentColor"':'')+'><path d="m12 3 2.8 5.7 6.2.9-4.5 4.4 1.1 6.2-5.6-3-5.6 3 1.1-6.2L3 9.6l6.2-.9Z"/></svg></button></div>'+agOwnerHTML(x)+(x.sourceTaskId?'<button class="ag-source-task" title="'+attr(tr('Generated from Task'))+'" onclick="agOpenSourceTask('+jsq(x.sourceTaskId)+')">'+I.tasks+'<span>'+tr('Generated from Task')+' · <b data-no-translate>'+esc((task(x.sourceTaskId)||{}).title||x.sourceTaskTitle||x.sourceTaskId)+'</b></span></button>':'')+'<div class="ag-tags">'+x.tags.map(function(t){return '<span data-no-translate>'+esc(t)+'</span>';}).join('')+'</div>'+(x.notes?'<details class="ag-note"><summary>'+tr('Design notes')+'</summary><p data-no-translate>'+esc(x.notes)+'</p></details>':'')+'</div><footer class="ag-card-footer"><div class="ag-card-actions">'+(!x.archived&&agCanSave()?'<button class="btn primary xs" onclick="agDuplicateModal(\''+x.id+'\')">'+tr('Duplicate & edit')+'</button>':'')+(x.ownerId===ME&&!x.archived&&agCanSave()?'<button class="btn xs" onclick="agOpen(\''+x.id+'\')">'+tr('Edit')+'</button>':'')+(agManage(x)?'<button class="btn xs" onclick="agManageModal(\''+x.id+'\')">'+tr('Manage')+'</button>':'')+'</div></footer></article>';}
function agCards(){var el=document.getElementById('agItems');if(!el)return;el.innerHTML=AG.items.length?'<div class="ag-grid">'+AG.items.map(agCardHTML).join('')+'</div><div class="ag-pagination"><button class="btn" '+(AG.offset===0?'disabled':'')+' onclick="AG.offset-=24;renderAIGallery()">'+tr('Previous')+'</button><span>'+(AG.offset+1)+'–'+(AG.offset+AG.items.length)+' / '+AG.total+'</span><button class="btn" '+(AG.offset+24>=AG.total?'disabled':'')+' onclick="AG.offset+=24;renderAIGallery()">'+tr('Next')+'</button></div>':'<div class="panel ag-empty">'+I.gallery+'<h2>'+tr('No designs here yet')+'</h2><p>'+tr('Save a design from AI Hub, or try another search.')+'</p><div class="ag-empty-actions"><button class="btn primary" onclick="go(\'aihub\')">'+I.sparkle+tr('Open AI Hub')+'</button>'
 +(AG.mode==='all'&&!AG.q?'':'<button class="btn" onclick="agShowAll()">'+I.gallery+tr('View all gallery designs')+'</button>')+'</div></div>';}
function agOpenSourceTask(id){ if(task(id)) openTask(id); else toast(tr('This task is no longer available to you.'),'bad'); }
function agItem(id){return AG.items.find(function(x){return x.id===id;});}
async function agFavorite(id){var x=agItem(id);try{await agRequest('POST','/'+id+'/favorite',{favorite:!x.favorite});x.favorite=!x.favorite;if(AG.mode==='favorites')renderAIGallery();else agCards();}catch(e){agError(e);}}
async function agDetails(id){try{var x=await agRequest('GET','/'+id),source=null;if(x.sourceId){try{source=await agRequest('GET','/'+x.sourceId);}catch(e){}}openModal('Design details','<img class="ag-detail-image" src="'+attr(x.thumb)+'" alt=""><h2 data-no-translate>'+esc(x.name)+'</h2><p>'+tr('Owner')+': '+esc(person(x.ownerId).name)+'</p><p>'+tr('Layers')+': '+(6+(x.fields.extraLayers||[]).length)+'</p>'+(x.sourceId?'<p>'+tr('Copied from')+': <span data-no-translate>'+esc(source?source.name:tr('Original unavailable'))+'</span></p>':'')+'<section class="ag-detail-notes"><h3>'+tr('Design notes')+'</h3><p data-no-translate>'+esc(x.notes||tr('No notes yet.'))+'</p></section><details><summary>'+tr('Design prompt')+'</summary><p data-no-translate>'+esc(x.fields.prompt||x.fields.brief||'—')+'</p></details>','<button class="btn" onclick="closeModal()">'+tr('Close')+'</button>'+(!x.archived&&agCanDuplicate()?'<button class="btn primary" onclick="agDuplicateModal(\''+id+'\')">'+tr('Duplicate & edit')+'</button>':''),true);}catch(e){agError(e);}}
function agDuplicateModal(id){var x=agItem(id);if(!x)return;openModal('Duplicate design','<div class="field"><label>'+tr('File name')+'</label><input id="agCopyName" maxlength="120" value="'+attr((x.name+' — '+first(ME)).slice(0,120))+'"></div>'+agNotesField('agCopyNotes',x.notes)+'<p class="hint">'+tr('Your copy keeps all layers. The original stays unchanged.')+'</p>','<button class="btn" onclick="closeModal()">'+tr('Cancel')+'</button><button id="agCopyBtn" class="btn primary" onclick="agDuplicate(\''+id+'\')">'+tr('Duplicate & edit')+'</button>');}
async function agDuplicate(id){var gate=agCanCreate('duplicate');if(!gate.ok)return toast(gate.message,'bad');var btn=document.getElementById('agCopyBtn');btn.disabled=true;try{var item=await agRequest('POST','/'+id+'/duplicate',{name:val('agCopyName'),notes:val('agCopyNotes')});agQuotaBump('duplicate');AG_OWNED_COUNT=null;agRefreshOwnedCount();closeModal();await agOpen(item.id);}catch(e){btn.disabled=false;agError(e);}}
async function agOpen(id){try{var x=await agRequest('GET','/'+id);if(!x)throw Error(tr('Gallery design not found.'));if(x.archived)throw Error(tr('Restore the design before editing it.'));if(x.ownerId!==ME)throw Error(tr('Only the owner can edit this design. Use Duplicate & edit to make your own copy.'));if(!agCanSave())throw Error(tr('Your role can view AI Gallery but cannot save designs.'));AIF=Object.assign(clone(AG_DEFAULT_FIELDS),clone(x.fields||{}));AI_HISTORY=[];AI_REDO=[];AIF.selectedLayer='canvas';AIF.selectedLayers=[];AI_LAST=x.image?{imgUrl:x.image,fields:clone(x.fields),at:x.createdAt}:null;AG_EDIT=x;AI_PROJECT_BASE=null;closeModal();go('aihub');setTimeout(aiProjectMarkSaved,0);}catch(e){agError(e);}}
function agManageModal(id){var x=agItem(id);openModal('Manage design','<div class="field"><label>'+tr('File name')+'</label><input id="agRename" maxlength="120" value="'+attr(x.name)+'"></div><div class="field"><label>'+tr('Tags')+'</label>'+tagPicker('agEditTags',x.tags||[],'')+'</div>'+agNotesField('agEditNotes',x.notes),'<button class="btn" onclick="agArchive(\''+id+'\','+!x.archived+')">'+tr(x.archived?'Restore':'Archive')+'</button><button class="btn primary" onclick="agRename(\''+id+'\')">'+tr('Save changes')+'</button>');}
async function agRename(id){try{var x=agItem(id);await agRequest('PATCH','/'+id,{name:val('agRename'),tags:tagPickerValues('agEditTags'),notes:val('agEditNotes'),revision:x.revision});closeModal();renderAIGallery();}catch(e){agError(e);}}
async function agArchive(id,archived){try{var x=agItem(id);await agRequest('PATCH','/'+id,{archived:archived,revision:x.revision});closeModal();renderAIGallery();}catch(e){agError(e);}}
