function setAvailability(state,extra){ var p=myPrefs(); if(state==="available"){ p.availability=null; } else if(state==="ooo"||state==="vacation"||state==="sick"){ if(!extra){ closePops(); var d=new Date(); d.setDate(d.getDate()+(state==="sick"?1:3)); openModal(tr(AVAIL[state].label),'<div class="field"><label>'+tr("Back on")+'</label><input type="date" id="stUntil" value="'+d.toISOString().slice(0,10)+'"></div>','<button class="btn" onclick="closeModal()">'+tr("Cancel")+'</button><button class="btn primary" onclick="var u=val(\'stUntil\');closeModal();setAvailability(\''+state+'\',{until:u?new Date(u+\'T23:59:00\').toISOString():null})">'+tr("Save")+'</button>'); return; } p.availability=Object.assign({state:state,emoji:AVAIL[state].emoji,text:""},extra); } else { var until=null; if(state==="meeting"||state==="lunch"||state==="focus"){ until=new Date(Date.now()+(state==="lunch"?60:state==="meeting"?60:120)*60000).toISOString(); } p.availability=Object.assign({state:state,emoji:AVAIL[state].emoji,text:"",until:until},extra||{}); } saveMyPrefs(); var m=document.getElementById("userMenu"); if(m&&m.classList.contains("open")){ m.innerHTML=userMenuHtml(); localizeVisibleText(m); } renderNav(); if(S.screen==="messages"){ if(typeof renderMsgNav==="function") renderMsgNav(); if(typeof renderMsgDetail==="function") renderMsgDetail(); if(typeof renderMsgTimeline==="function"&&document.getElementById("msgTimeline")) renderMsgTimeline(true); } if(S.screen==="settings"&&S.settingsTab==="profile") renderScreen(false); if(S.drawerTask) renderDrawer(); toast(tr(state==="available"?"Status cleared":"Status updated")); }
function statusDefaultUntil(k){ var d=new Date(); if(k==="focus") return new Date(d.getTime()+120*60000); if(k==="meeting"||k==="lunch"||k==="commuting") return new Date(d.getTime()+60*60000); if(k==="sick"){ d.setDate(d.getDate()+1); d.setHours(23,59,0,0); return d; } if(k==="vacation"){ d.setDate(d.getDate()+3); d.setHours(23,59,0,0); return d; } return null; }
function statusDefaultUntilLabel(k){ var d=statusDefaultUntil(k); if(!d) return ""; var mins=Math.round((d-new Date())/60000); if(mins<=180) return mins>=60?Math.round(mins/60)+" "+tr(mins>=120?"hours":"hour"):mins+" "+tr("min"); return d.toLocaleDateString([],{weekday:"short"}); }
function statusUntilLocal(d){ return d?new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,16):""; }
function statusQuickUntil(kind){ var d=new Date(); if(kind==="30m") d=new Date(d.getTime()+30*60000); else if(kind==="1h") d=new Date(d.getTime()+60*60000); else if(kind==="2h") d=new Date(d.getTime()+120*60000); else if(kind==="today"){ d.setHours(18,0,0,0); if(d<=new Date()) d.setHours(23,59,0,0); } else if(kind==="tomorrow"){ d.setDate(d.getDate()+1); d.setHours(9,0,0,0); } else d=null; var i=document.getElementById("stUntil"); if(i) i.value=statusUntilLocal(d); document.querySelectorAll(".st-until-quick button").forEach(function(b){ b.classList.toggle("on",b.getAttribute("data-k")===kind); }); }
