function statusModal(preset){ var cur=availabilityOf(ME), isPreset=!!(preset&&AVAIL[preset]&&preset!=="custom"); window._stPreset=isPreset?preset:(!preset&&cur.state!=="available"&&cur.state!=="custom"?cur.state:null); window._stEmoji=isPreset?AVAIL[preset].emoji:(cur.state!=="available"?(cur.emoji||"💬"):"💬"); var text=isPreset?tr(AVAIL[preset].label):(cur.state!=="available"?(cur.text||tr(AVAIL[cur.state].label)):""); var untilD=isPreset?statusDefaultUntil(preset):(cur.until?new Date(cur.until):null); var until=statusUntilLocal(untilD); var quick=[["30m","30 min"],["1h","1 hour"],["2h","2 hours"],["today","End of today"],["tomorrow","Tomorrow"],["never","Don't clear"]]; openModal(tr("Set a status"),'<div class="st-edit"><button class="st-emoji" id="stEmojiBtn" data-menu aria-haspopup="menu" title="'+attr(tr("Change emoji"))+'" onclick="emojiPicker(this,function(e){window._stEmoji=e;document.getElementById(\'stEmojiBtn\').innerHTML=emojiHtml(e,\'st\')})">'+emojiHtml(window._stEmoji,"st")+'</button><input id="stText" maxlength="60" placeholder="'+attr(tr("What\'s your status?"))+'" value="'+attr(text)+'"></div><div class="st-suggest">'+["focus","meeting","lunch","remote","commuting","sick","vacation","ooo"].map(function(k){ return '<button class="'+(window._stPreset===k?"on":"")+'" onclick="statusPickPreset(this,\''+k+'\')">'+emojiHtml(AVAIL[k].emoji,"st")+tr(AVAIL[k].label)+'</button>'; }).join("")+'</div><div class="field"><label>'+tr("Clear after")+'</label><div class="st-until-quick">'+quick.map(function(q){ return '<button type="button" data-k="'+q[0]+'" onclick="statusQuickUntil(\''+q[0]+'\')">'+tr(q[1])+'</button>'; }).join("")+'</div><input type="datetime-local" id="stUntil" value="'+until+'" oninput="document.querySelectorAll(\'.st-until-quick button\').forEach(function(b){b.classList.remove(\'on\')})"></div><p class="hint">'+tr("Leave it empty to keep the status until you clear it.")+'</p>','<button class="btn" onclick="closeModal()">'+tr("Cancel")+'</button>'+(cur.state!=="available"?'<button class="btn" onclick="closeModal();setAvailability(\'available\')">'+tr("Clear status")+'</button>':'')+'<span class="spacer"></span><button class="btn primary" onclick="var t=val(\'stText\');if(!t)return toast(tr(\'Write a status first\'),\'bad\');var u=val(\'stUntil\');closeModal();setAvailability(window._stPreset||\'custom\',{emoji:window._stEmoji,text:t,until:u?new Date(u).toISOString():null})">'+tr("Save")+'</button>'); }
