function checklistEdit(id,i){ var tk=task(id); if(!chkCanEdit(tk)||!chkItems(tk)[i]) return; if(CHK.edit){ if(CHK.edit.id===id&&chkEditIndex(tk)===i) return; checklistEditDone(true); } var it=chkItems(tk)[i]; if(!it) return; CHK.edit={id:id,i:i,orig:it.text,draft:it.text}; chkRowSwap(tk,i); var el=document.getElementById("chkEdit"); if(el){ el.focus(); var n=el.value.length; try{ el.setSelectionRange(n,n); }catch(x){} } }
