function ddRow(label,help,control,extra){ return '<div class="pref'+(extra?" "+extra:"")+'"><div class="pl"><b>'+tr(label)+'</b>'+(help?'<span>'+tr(help)+'</span>':'')+'</div>'+control+'</div>'; }
