    + '<div class="dd-meta">'+[who,f.size,f.createdAt?ago(null,f.createdAt):""].filter(Boolean).map(function(x){ return '<span>'+x+'</span>'; }).join('<span>·</span>')+(usage?'<span>·</span>'+usage:'')+'</div>'
